import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cute_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""

cute_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>
#include <cute/arch/copy_sm80.hpp>

using namespace cute;

// GEMM kernel: C(M,N) = A(M,K) * B(K,N)
// mA is a direct (M,K) row-major view of A.
// mB is a (N,K) view of B (B is stored (K,N) row-major, so mB(n,k) = B[k,n]).
// mC is a direct (M,N) row-major view of C.
template <class TA, class TB, class TC>
__global__ static void
gemm_device(cute::Shape<int,int,int> shape_MNK,
            TA const* A, cute::Stride<int,int> dA,
            TB const* B, cute::Stride<int,int> dB,
            TC      * C, cute::Stride<int,int> dC,
            int split_k)
{
  using namespace cute;
  int M = get<0>(shape_MNK);
  int N = get<1>(shape_MNK);
  int K = get<2>(shape_MNK);
  // Represent full tensors
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), dA); // (M,K)
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), dB); // (N,K)
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), dC); // (M,N)
  // Tile sizes: BLK_M=128, BLK_N=128, BLK_K=32
  auto cta_tiler = make_shape(Int<128>{}, Int<128>{}, Int<32>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,X,_1>{}); // (128,32,K_TILES)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X,_1,_1>{}); // (128,32,K_TILES)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,X>{}); // (128,128)
  // Double-buffered shared memory tiles for software pipelining of
  // global->shared loads with compute across K-tile iterations.
  constexpr int NSTAGE = 2;
  extern __shared__ char smem_raw[];
  TA* smemA = reinterpret_cast<TA*>(smem_raw);
  TB* smemB = reinterpret_cast<TB*>(smem_raw + NSTAGE * 128 * 32 * sizeof(TA));
  Tensor sA0 = make_tensor(make_smem_ptr(smemA + 0*128*32), make_shape(Int<128>{}, Int<32>{}));
  Tensor sA1 = make_tensor(make_smem_ptr(smemA + 1*128*32), make_shape(Int<128>{}, Int<32>{}));
  Tensor sB0 = make_tensor(make_smem_ptr(smemB + 0*128*32), make_shape(Int<128>{}, Int<32>{}));
  Tensor sB1 = make_tensor(make_smem_ptr(smemB + 1*128*32), make_shape(Int<128>{}, Int<32>{}));
  // Thread layouts for staging (loading) and compute
  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));
  using CopyAtomA = Copy_Atom<SM80_CP_ASYNC_CACHEALWAYS<TA>, TA>;
  using CopyAtomB = Copy_Atom<SM80_CP_ASYNC_CACHEALWAYS<TB>, TB>;
  // Value layout per thread: each thread handles a 4x4 sub-tile so that
  // ThrLayout * ValLayout exactly covers the (BLK_M,BLK_K) / (BLK_N,BLK_K)
  // CTA tile. The underlying Copy_Atom moves a single element per call;
  // TiledCopy loops it internally to cover the full ValLayout, and its
  // partition_S/partition_D produce fragments whose leading (CPY) mode
  // matches the atom's contract exactly (unlike raw local_partition).
  auto val_layout = make_layout(make_shape(Int<4>{}, Int<4>{}));
  auto tiled_copy_a = make_tiled_copy(CopyAtomA{}, tA, val_layout);
  auto tiled_copy_b = make_tiled_copy(CopyAtomB{}, tB, val_layout);
  auto thr_copy_a = tiled_copy_a.get_slice(threadIdx.x);
  auto thr_copy_b = tiled_copy_b.get_slice(threadIdx.x);
  Tensor tAgA = thr_copy_a.partition_S(gA);   // (CPY,CPY_M,CPY_K,K_TILES)
  Tensor tAsA0 = thr_copy_a.partition_D(sA0); // (CPY,CPY_M,CPY_K)
  Tensor tAsA1 = thr_copy_a.partition_D(sA1); // (CPY,CPY_M,CPY_K)
  Tensor tBgB = thr_copy_b.partition_S(gB);   // (CPY,CPY_N,CPY_K,K_TILES)
  Tensor tBsB0 = thr_copy_b.partition_D(sB0); // (CPY,CPY_N,CPY_K)
  Tensor tBsB1 = thr_copy_b.partition_D(sB1); // (CPY,CPY_N,CPY_K)
  Tensor tCsA0 = local_partition(sA0, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsA1 = local_partition(sA1, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsB0 = local_partition(sB0, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCsB1 = local_partition(sB1, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  int K_TILE_TOTAL = size<3>(tAgA);
  int k_tiles_per_split = (K_TILE_TOTAL + split_k - 1) / split_k;
  int k_tile_start = blockIdx.z * k_tiles_per_split;
  int k_tile_end = k_tile_start + k_tiles_per_split;
  if (k_tile_end > K_TILE_TOTAL) k_tile_end = K_TILE_TOTAL;
  if (k_tile_start < k_tile_end) {
    // Prime the pipeline: issue a real cp.async load for the first K-tile.
    copy(tiled_copy_a, tAgA(_,_,_,k_tile_start), tAsA0);
    copy(tiled_copy_b, tBgB(_,_,_,k_tile_start), tBsB0);
    cp_async_fence();
    for (int k_tile = k_tile_start; k_tile < k_tile_end; ++k_tile) {
      int cur = (k_tile - k_tile_start) % NSTAGE;
      bool has_next = (k_tile + 1) < k_tile_end;
      if (has_next) {
        int nxt = (k_tile + 1 - k_tile_start) % NSTAGE;
        if (nxt == 0) {
          copy(tiled_copy_a, tAgA(_,_,_,k_tile+1), tAsA0);
          copy(tiled_copy_b, tBgB(_,_,_,k_tile+1), tBsB0);
        } else {
          copy(tiled_copy_a, tAgA(_,_,_,k_tile+1), tAsA1);
          copy(tiled_copy_b, tBgB(_,_,_,k_tile+1), tBsB1);
        }
        cp_async_fence();
        // Keep the just-issued prefetch (1 group) outstanding while
        // waiting for the previously issued load to complete.
        cp_async_wait<1>();
      } else {
        cp_async_wait<0>();
      }
      __syncthreads();
      if (cur == 0) {
        gemm(tCsA0, tCsB0, tCrC);
      } else {
        gemm(tCsA1, tCsB1, tCrC);
      }
      __syncthreads();
    }
  }
  // Epilogue: accumulate partial results across split-K blocks
  if (split_k == 1) {
    axpby(1.0f, tCrC, 0.0f, tCgC);
  } else {
    CUTE_UNROLL
    for (int i = 0; i < size(tCrC); ++i) {
      atomicAdd(&tCgC(i), tCrC(i));
    }
  }
}

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim()==2 && B.dim()==2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type()==at::kFloat && B.scalar_type()==at::kFloat,
              "Expect float32 tensors");
  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
  TORCH_CHECK((int)B.size(0)==K, "Inner dimensions of A and B must match");
  TORCH_CHECK(M % 128 == 0 && N % 128 == 0 && K % 32 == 0,
              "This kernel requires M,N multiples of 128 and K a multiple of 32");
  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  // Compute a split-K factor so that the grid (grid.x * grid.y * grid.z)
  // has enough blocks to fill the GPU's SMs. This matters when K is very
  // large relative to M and N, which otherwise produces a tiny grid.
  // Query the actual device SM count instead of assuming a fixed number
  // so the split-K factor adapts to the real hardware and provides
  // enough blocks (targeting multiple blocks per SM) to fill the GPU,
  // improving occupancy for small-M/N, large-K shapes like this one.
  int K_TILES = K / 32;
  int mn_blocks = (M / 128) * (N / 128);
  int cur_device = 0;
  cudaGetDevice(&cur_device);
  cudaDeviceProp dev_prop;
  cudaGetDeviceProperties(&dev_prop, cur_device);
  int sm_count = dev_prop.multiProcessorCount;
  if (sm_count <= 0) sm_count = 132; // fallback
  int target_blocks = sm_count * 4; // aim for several blocks per SM
  int split_k = (target_blocks + mn_blocks - 1) / mn_blocks;
  if (split_k < 1) split_k = 1;
  if (split_k > K_TILES) split_k = K_TILES;
  torch::Tensor C;
  if (split_k > 1) {
    // Multiple blocks along K atomically accumulate into C, so it must
    // start at zero.
    C = torch::zeros({M, N}, A.options());
  } else {
    C = torch::empty({M, N}, A.options());
  }
  auto ptrA = A_c.data_ptr<float>();
  auto ptrB = B_c.data_ptr<float>();
  auto ptrC = C.data_ptr<float>();
  // A stored row-major (M,K): stride (K,1)
  auto dA = make_stride(K, 1);
  // B stored row-major (K,N); viewed as (N,K) with mB(n,k) = B[k,n]: stride (1,N)
  auto dB = make_stride(1, N);
  // C stored row-major (M,N): stride (N,1)
  auto dC = make_stride(N, 1);
  auto shape_MNK = make_shape(M, N, K);
  constexpr int NSTAGE_HOST = 2;
  size_t smem_bytes = (size_t)NSTAGE_HOST * 128 * 32 * sizeof(float) * 2;
  static bool attr_set = false;
  if (!attr_set) {
    cudaFuncSetAttribute(
        gemm_device<float,float,float>,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        (int)smem_bytes);
    attr_set = true;
  }
  dim3 dimBlock(256);
  dim3 dimGrid(M/128, N/128, split_k);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemm_device<<<dimGrid, dimBlock, smem_bytes, stream>>>(shape_MNK, ptrA, dA, ptrB, dB, ptrC, dC, split_k);
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));
  return C;
}
"""

cute_matmul_ext = load_inline(
    name="cute_matmul_inline",
    cpp_sources=cute_cpp_decl,
    cuda_sources=cute_cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B)
    using a custom CUTE-based GEMM kernel.
    """
    def __init__(self) -> None:
        super().__init__()
        self._ext = cute_matmul_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matmul(A, B)

